#include <cstdio>
#include <cstring>
#include <algorithm>
#include <array>
#include <stack>

#define N_F 1010
#define N_CONST 1001

using namespace std;

int v, d, f1, f2;
std::array<unsigned long long int, N_F> f;
std::array<std::array<int, N_CONST + 10>, N_CONST + 10> node;

void rmNode(int i) {
    node[i][i] = 0;
    std::stack<int> s;
    s.push(i);
    while (!s.empty()) {
        int current = s.top();
        s.pop();
        for (int j = 0; j < N_CONST; j++) {
            if (node[j][j] == 0) continue;
            if (node[current][j] == 1) {
                node[current][j] = 0; // Mark as removed
                s.push(j); // Add to stack for further processing
            }
        }
    }
}

int main() {
    f[0] = 1; f[1] = 2;
    for (int i = 2; i < N_F; i++) {
        f[i] = (f[i - 1] + f[i - 2]) % N_CONST;
    }

    while (scanf("%d %d", &v, &d) == 2) {
        memset(node.data(), 0, sizeof(node));
        for (int i = 1; i <= v; i++) {
            f1 = f[i] % N_CONST;
            node[f1][f1] = 1;

            for (int j = 1; j <= v; j++) {
                f2 = f[j] % N_CONST;
                if (abs(f1 - f2) < d) {
                    node[f1][f2] = 1;
                    node[f2][f1] = 1;
                }
            }
        }

        int n = 0;
        for (int i = 0; i < N_CONST; i++) {
            if (node[i][i] == 0) continue;
            n++;
            rmNode(i);
        }
        printf("%d\n", n);
    }

    return 0;
}

